<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Appointment;use App\Models\MedicalRecord;use App\Models\Pasien;use Illuminate\Support\Carbon;
class DashboardController extends Controller { public function __invoke(){ $today=now()->toDateString();$week=collect(range(6,0))->map(function($days){$d=now()->subDays($days);return ['label'=>$d->translatedFormat('D'),'date'=>$d->toDateString(),'count'=>Appointment::whereDate('scheduled_at',$d)->count()];});return response()->json(['stats'=>['patients'=>Pasien::count(),'today'=>Appointment::whereDate('scheduled_at',$today)->count(),'waiting'=>Appointment::whereDate('scheduled_at',$today)->where('status','Menunggu')->count(),'completed'=>Appointment::whereDate('scheduled_at',$today)->where('status','Selesai')->count(),'records'=>MedicalRecord::count()],'week'=>$week,'todayAppointments'=>Appointment::with(['patient','doctor'])->whereDate('scheduled_at',$today)->orderBy('scheduled_at')->get(),'recentRecords'=>MedicalRecord::with(['patient','doctor'])->latest('visited_at')->limit(5)->get()]);} }
